ernal-record://abiogenesis/.ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-material-selection-02/request.txt"},{"byteCount":6274,"digest":"sha256:54411d51f4e8391963f067f28323ace96381be4a6c081206d4482d2761596700","path":".ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-material-selection-02/freeze.json","ref":"external-record://abiogenesis/.ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-material-selection-02/freeze.json"},{"byteCount":2459857,"digest":"sha256:a5190e6168c0dce8312f58acfe9b662c4cc320649764cf918b10353f42039d71","path":".ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-material-selection-02/construction-checks.json","ref":"external-record://abiogenesis/.ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-material-selection-02/construction-checks.json"},{"byteCount":45378,"digest":"sha256:d9a15ca4cc92fa342a6ec3796441ba25d1c9678cfd09ca43aec5cd83b236989e","path":".ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-material-selection-02/selection-rationale.json","ref":"material://abiogenesis/final-f11-material-selection-02/selection-rationale"},{"byteCount":353,"digest":"sha256:43f6d9cab3d0b105bfe786a87d1eb74e25cbe47eaa757b7f8669a0e5c969e722","path":".ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-bound-assessment-01/derived/material02-rationale-preimage.json","ref":"derived-record://abiogenesis/.ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-bound-assessment-01/derived/material02-rationale-preimage.json"},{"byteCount":46335,"digest":"sha256:dfaffe938e333f58ad449c9c23ea8cb072fe513b639886b700bececa8971bd0f","path":".ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-bound-assessment-01/derived/material02-rationale-create-view.patch","ref":"derived-record://abiogenesis/.ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/final-f11-bound-assessment-01/derived/material02-rationale-create-view.patch"},{"byteCount":857