"import {\n  canonicalJson,\n  compareUnicodeCodeUnits,\n  type JsonValue,\n} from \"../shared/canonical_json.js\";\nimport { deepFreeze } from \"../shared/immutable.js\";\nimport { requireRef } from \"../shared/references.js\";\nimport { COMPUTE_REGIME_VALUES } from \"./c_algebra.js\";\nimport { canonicalizeAuthoredGtlCarrier } from \"./canonicalization.js\";\nimport type {\n  CatalogContribution,\n  ClosureContract,\n  ContractDeclaration,\n  EvaluatorDeclaration,\n  ImplementationBinding,\n  ModulePublication,\n  ProductSemanticsBinding,\n  RuleDeclaration,\n} from \"./contracts.js\";\n\nconst CONTRACT_KINDS = [\n  \"closure\",\n  \"evidence\",\n  \"failure\",\n  \"input\",\n  \"judgment\",\n  \"output\",\n  \"refusal\",\n  \"transition\",\n] as const;\n\nfunction freezeStrings(\n  values: readonly string[],\n  label: string,\n): readonly string[] {\n  if (values.some((value) => value.trim().length === 0)) {\n    throw new TypeError(`${label} cannot contain an empty reference`);\n  }\n  return Object.freeze([...values].sort(compareUnicodeCodeUnits));\n}\n\nfunction cloneJsonObject(\n  value: Readonly<Record<string, JsonValue>>,\n): Readonly<Record<string, JsonValue>> {\n  if (value === null || Array.isArray(value) || typeof value !== \"object\") {\n    throw new TypeError(\"Rule.config must be one JSON object\");\n  }\n  return JSON.parse(canonicalJson(value)) as Readonly<Record<string, JsonValue>>;\n}\n\nexport function evaluatorDeclaration(\n  input: Readonly<EvaluatorDeclaration>,\n): EvaluatorDeclaration {\n  requireRef(input.name, \"Evaluator.name\");\n  requireRef(input.binding, \"Evaluator.binding\");\n  if (!COMPUTE_REGIME_VALUES.includes(input.regime)) {\n    throw new TypeError(\"Evaluator.regime must be F_D, F_P, or F_H\");\n  }\n  return deepFreeze({\n    name: input.name,\n    regime: input.regime,\n    description: input.description,\n    binding: input.binding,\n    consumedFieldRefs: freezeStrings(\n      input.consumedFieldRefs,\n      \"Evaluator.consumedFieldRefs\",\n    ),\n    tags: freezeStrings(input.tags, \"Evaluator.tags\"),\n  });\n}\n\nexport function ruleDeclaration(\n  input: Readonly<RuleDeclaration>,\n): RuleDeclaration {\n  requireRef(input.name, \"Rule.name\");\n  requireRef(input.kind, \"Rule.kind\");\n  return deepFreeze({\n    name: input.name,\n    kind: input.kind,\n    config: cloneJsonObject(input.config),\n    tags: freezeStrings(input.tags, \"Rule.tags\"),\n  });\n}\n\nexport function contractDeclaration(\n  input: Readonly<ContractDeclaration>,\n): ContractDeclaration {\n  requireRef(input.contractRef, \"Contract.contractRef\");\n  requireRef(input.valueKind, \"Contract.valueKind\");\n  if (\n    input.contractVersion !== \"5.0.0\" ||\n    !CONTRACT_KINDS.includes(input.contractKind)\n  ) {\n    throw new TypeError(\"Contract requires the declared 5.0.0 kind\");\n  }\n  return deepFreeze({ ...input });\n}\n\nexport function implementationBinding(\n  input: Readonly<ImplementationBinding>,\n): ImplementationBinding {\n  for (const [label, value] of Object.entries(input)) {\n    if (label !== \"kind\" && label !== \"computeRegime\") {\n      requireRef(value, `ImplementationBinding.${label}`);\n    }\n  }\n  if (\n    input.kind !== \"implementation_binding\" ||\n    (input.computeRegime !== \"F_D\" && input.computeRegime !== \"F_P\")\n  ) {\n    throw new TypeError(\"ImplementationBinding requires one F_D or F_P leaf\");\n  }\n  return deepFreeze({ ...input });\n}\n\nexport function productSemanticsBinding(\n  input: Readonly<ProductSemanticsBinding>,\n): ProductSemanticsBinding {\n  for (const [label, value] of Object.entries(input)) {\n    if (label !== \"kind\") {\n      requireRef(value, `ProductSemanticsBinding.${label}`);\n    }\n  }\n  if (input.kind !== \"product_semantics_binding\") {\n    throw new TypeError(\"ProductSemanticsBinding.kind is invalid\");\n  }\n  return deepFreeze({ ...input });\n}\n\nexport function closureContract(\n  input: Readonly<ClosureContract>,\n): ClosureContract {\n  for (const [label, value] of Object.entries(input)) {\n    if (\n      label !== \"eventKindRefs\" &&\n      label !== \"kind\" &&\n      label !== \"terminalKind\" &&\n      label !== \"closureScope\"\n    ) {\n      requireRef(value, `ClosureContract.${label}`);\n    }\n  }\n  const expectedEvents = input.closureScope === \"run\"\n    ? [\"terminal_reached\", \"frame_closed\", \"graph_call_closed\", \"run_closed\"]\n    : [\"terminal_reached\", \"frame_closed\", \"graph_call_closed\"];\n  if (\n    input.kind !== \"closure_contract\" ||\n    input.terminalKind !== \"completed\" ||\n    input.eventKindRefs.join(\"\\0\") !== expectedEvents.join(\"\\0\")\n  ) {\n    throw new TypeError(\n      \"ClosureContract scope requires its exact terminal event sequence\",\n    );\n  }\n  return deepFreeze({\n    ...input,\n    eventKindRefs: [...input.eventKindRefs],\n  }) as ClosureContract;\n}\n\nexport function catalogContribution(\n  input: Readonly<CatalogContribution>,\n): CatalogContribution {\n  requireRef(input.handle, \"CatalogContribution.handle\");\n  requireRef(\n    input.declarationOrContractRef,\n    \"CatalogContribution.declarationOrContractRef\",\n  );\n  requireRef(input.owningProductId, \"CatalogContribution.owningProductId\");\n  if (\n    input.kind !== \"graph_function\" &&\n    input.kind !== \"node_type\" &&\n    input.kind !== \"overlay\"\n  ) {\n    throw new TypeError(\"CatalogContribution.kind is invalid\");\n  }\n  return deepFreeze({\n    ...input,\n    programMembershipRefs: freezeStrings(\n      input.programMembershipRefs,\n      \"CatalogContribution.programMembershipRefs\",\n    ),\n    readinessPrerequisiteRefs: freezeStrings(\n      input.readinessPrerequisiteRefs,\n      \"CatalogContribution.readinessPrerequisiteRefs\",\n    ),\n    compatibilityRefs: freezeStrings(\n      input.compatibilityRefs,\n      \"CatalogContribution.compatibilityRefs\",\n    ),\n    provenanceRefs: freezeStrings(\n      input.provenanceRefs,\n      \"CatalogContribution.provenanceRefs\",\n    ),\n  });\n}\n\nexport function modulePublication(\n  input: Readonly<ModulePublication>,\n): Readonly<ModulePublication> {\n  requireRef(input.moduleRef, \"ModulePublication.moduleRef\");\n  requireRef(input.owningProductId, \"ModulePublication.owningProductId\");\n  requireRef(input.descriptorRef, \"ModulePublication.descriptorRef\");\n  requireRef(\n    input.contributionManifestRef,\n    \"ModulePublication.contributionManifestRef\",\n  );\n  if (\n    input.kind !== \"module_publication\" ||\n    input.moduleVersion !== \"5.0.0\"\n  ) {\n    throw new TypeError(\"ModulePublication requires the 5.0.0 carrier\");\n  }\n  return canonicalizeAuthoredGtlCarrier({\n    ...input,\n    productSemanticsBinding: productSemanticsBinding(\n      input.productSemanticsBinding,\n    ),\n    contracts: input.contracts.map(contractDeclaration),\n    evaluators: input.evaluators.map(evaluatorDeclaration),\n    rules: input.rules.map(ruleDeclaration),\n    implementationBindings:\n      input.implementationBindings.map(implementationBinding),\n    closureContracts: input.closureContracts.map(closureContract),\n    programs: [...input.programs],\n    graphFunctions: [...input.graphFunctions],\n    contributions: input.contributions.map(catalogContribution),\n  }, \"module_publication\");\n}\n\nexport const GTL_DECLARATION_CONSTRUCTORS = deepFreeze({\n  catalogContribution,\n  closureContract,\n  contractDeclaration,\n  implementationBinding,\n  modulePublication,\n  productSemanticsBinding,\n});\n"

SOURCE DATA repo://abiogenesis/build_tenants/abiogenesis/typescript/code/src/gtl/materialize.ts sha256:d1fa94c4cde7968552e41a6a99ae7b57b7470b4e0c9c4ab65d9bb1e5873e5e59
"import { isJsonRecordShape as isRecord } from \"../shared/admission_predicates.js\";\nimport type { JsonValue } from \"../shared/canonical_json.js\";\nimport { sha256Canonical } from \"../shared/digests.js\";\nimport { deepFreeze } from \"../shared/immutable.js\";\nimport type {\n  FanOutMaterialization,\n  GraphFunction,\n  GraphMaterializationBasis,\n  GraphTemplate,\n  GtlGraph,\n} from \"./contracts.js\";\nimport type { CProgramNode } from \"./c_algebra.js\";\n\nconst materializedGraphs = new WeakSet<object>();\n\nexport function isMaterializedGtlGraph(value: object): boolean {\n  return materializedGraphs.has(value);\n}\n\nexport function rehydrateMaterializedGtlGraph(\n  value: unknown,\n): Readonly<GtlGraph> | null {\n  if (\n    typeof value !== \"object\" ||\n    value === null ||\n    Array.isArray(value) ||\n    Object.keys(value).sort().join(\"\\0\") !== [\n      \"admittedInputDigest\",\n      \"admittedInputRef\",\n      \"fanOutMaterializations\",\n      \"graphFunctionDigest\",\n      \"graphFunctionRef\",\n      \"invocationAdmissionRef\",\n      \"kind\",\n      \"materializationDigest\",\n      \"materializationRef\",\n      \"schemaVersion\",\n      \"template\",\n    ].join(\"\\0\")\n  ) {\n    return null;\n  }\n  const graph = value as Partial<GtlGraph>;\n  if (\n    graph.kind !== \"gtl_graph\" ||\n    graph.schemaVersion !== \"5.0.0\" ||\n    typeof graph.materializationRef !== \"string\" ||\n    typeof graph.materializationDigest !== \"string\" ||\n    typeof graph.graphFunctionRef !== \"string\" ||\n    typeof graph.graphFunctionDigest !== \"string\" ||\n    typeof graph.invocationAdmissionRef !== \"string\" ||\n    typeof graph.admittedInputRef !== \"string\" ||\n    typeof graph.admittedInputDigest !== \"string\" ||\n    !Array.isArray(graph.fanOutMaterializations) ||\n    typeof graph.template !== \"object\" ||\n    graph.template === null\n  ) {\n    return null;\n  }\n  const body = {\n    graphFunctionRef: graph.graphFunctionRef,\n    graphFunctionDigest: graph.graphFunctionDigest,\n    invocationAdmissionRef: graph.invocationAdmissionRef,\n    admittedInputRef: graph.admittedInputRef,\n    admittedInputDigest: graph.admittedInputDigest,\n    fanOutMaterializations: graph.fanOutMaterializations,\n    template: graph.template,\n  };\n  if (\n    graph.materializationDigest !==\n      sha256Canonical(body as unknown as JsonValue) ||\n    graph.materializationRef !==\n      `graph-materialization://abiogenesis/${graph.materializationDigest.slice(\"sha256:\".length)}`\n  ) {\n    return null;\n  }\n  materializedGraphs.add(value);\n  return value as Readonly<GtlGraph>;\n}\n\nexport interface MaterializedGraphShape {\n  readonly template: GraphTemplate;\n  readonly fanOutMaterializations: readonly FanOutMaterialization[];\n}\n\nfunction fanOutMembers(\n  basis: GraphMaterializationBasis,\n): FanOutMaterialization[\"members\"] {\n  const rows = basis.admittedInput.members;\n  if (!Array.isArray(rows) || rows.length === 0) {\n    throw new TypeError(\n      \"fan_out materialization requires one admitted non-empty ordered member vector\",\n    );\n  }\n  return deepFreeze(rows.map((row, ordinal) => {\n    if (!isRecord(row)) {\n      throw new TypeError(\n        \"fan_out members require stable zero-based ordinals, refs, and record values\",\n      );\n    }\n    const value = row.value;\n    if (\n      row.ordinal !== ordinal ||\n      typeof row.memberRef !== \"string\" ||\n      row.memberRef.length === 0 ||\n      !isRecord(value)\n    ) {\n      throw new TypeError(\n        \"fan_out members require stable zero-based ordinals, refs, and record values\",\n      );\n    }\n    return {\n      ordinal,\n      memberRef: row.memberRef,\n      memberDigest: sha256Canonical(value),\n      value,\n    };\n  }));\n}\n\nfunction projectBatch(\n  term: Readonly<CProgramNode>,\n  batchRef: string,\n  elementGraphFunctionRef: string,\n  taskCount: number,\n): { readonly term: CProgramNode; readonly matchCount: number } {\n  switch (term.kind) {\n    case \"c_of\":\n    case \"c_identity\":\n      return { term, matchCount: 0 };\n    case \"c_workflow\":\n      return { term, matchCount: 0 };\n    case \"c_compose\": {\n      const children = term.terms.map((child) =>\n        projectBatch(child, batchRef, elementGraphFunctionRef, taskCount));\n      return {\n        term: { ...term, terms: children.map((child) => child.term) },\n        matchCount: children.reduce((sum, child) => sum + child.matchCount, 0),\n      };\n    }\n    case \"c_edge\": {\n      const transform = projectBatch(\n        term.transform,\n        batchRef,\n        elementGraphFunctionRef,\n        taskCount,\n      );\n      const evaluate = projectBatch(\n        term.evaluate,\n        batchRef,\n        elementGraphFunctionRef,\n        taskCount,\n      );\n      const consequence = projectBatch(\n        term.consequence,\n        batchRef,\n        elementGraphFunctionRef,\n        taskCount,\n      );\n      return {\n        term: {\n          ...term,\n          transform: transform.term as typeof term.transform,\n          evaluate: evaluate.term as typeof term.evaluate,\n          consequence: consequence.term as typeof term.consequence,\n        },\n        matchCount:\n          transform.matchCount + evaluate.matchCount + consequence.matchCount,\n      };\n    }\n    case \"c_batch\": {\n      const children = term.tasks.map((child) =>\n        projectBatch(child, batchRef, elementGraphFunctionRef, taskCount));\n      if (term.batchRef !== batchRef) {\n        return {\n          term: { ...term, tasks: children.map((child) => child.term) },\n          matchCount: children.reduce((sum, child) => sum + child.matchCount, 0),\n        };\n      }\n      if (\n        term.tasks.length !== 1 ||\n        term.tasks[0]?.kind !== \"c_workflow\" ||\n        term.tasks[0].graphFunctionRef !== elementGraphFunctionRef\n      ) {\n        throw new TypeError(\n          \"fan_out batch requires one declared workflow.C element task seed\",\n        );\n      }\n      return {\n        term: {\n          ...term,\n          tasks: Array.from({ length: taskCount }, () => term.tasks[0]!),\n        },\n        matchCount:\n          1 + children.reduce((sum, child) => sum + child.matchCount, 0),\n      };\n    }\n    case \"c_retry\": {\n      const child = projectBatch(\n        term.term,\n        batchRef,\n        elementGraphFunctionRef,\n        taskCount,\n      );\n      return {\n        term: { ...term, term: child.term },\n        matchCount: child.matchCount,\n      };\n    }\n  }\n}\n\nexport function deriveMaterializedGraphShape(\n  graphFunction: Readonly<GraphFunction>,\n  basis: GraphMaterializationBasis,\n): MaterializedGraphShape {\n  const fanOutApplications = graphFunction.template.applications.filter(\n    (application) => application.relationKind === \"fan_out\",\n  );\n  if (fanOutApplications.length === 0) {\n    return deepFreeze({\n      template: graphFunction.template,\n      fanOutMaterializations: [],\n    });\n  }\n  if (\n    sha256Canonical(basis.admittedInput as unknown as JsonValue) !==\n      basis.admittedInputDigest\n  ) {\n    throw new TypeError(\n      \"graph materialization input value differs from the admitted input digest\",\n    );\n  }\n  const members = fanOutMembers(basis);\n  let nodes = [...graphFunction.template.nodes];\n  const fanOutMaterializations = fanOutApplications.map((application) => {\n    let matchCount = 0;\n    nodes = nodes.map((node) => {\n      const projected = projectBatch(\n        node.term,\n        application.batchRef,\n        application.elementGraphFunctionRef,\n        members.length,\n      );\n      matchCount += projected.matchCount;\n      return { ...node, term: projected.term };\n    });\n    if (matchCount !== 1) {\n      throw new TypeError(\n        \"fan_out application must bind exactly one declared C.batch\",\n      );\n    }\n    return {\n      applicationRef: application.applicationRef,\n      batchRef: application.batchRef,\n      inputVectorRef: application.inputVectorRef,\n      outputVectorRef: application.outputVectorRef,\n      inputMemberContractRef: application.inputMemberContractRef,\n      outputMemberContractRef: application.outputMemberContractRef,\n      members,\n    };\n  });\n  return deepFreeze({\n    template: {\n      ...graphFunction.template,\n      nodes,\n    },\n    fanOutMaterializations,\n  });\n}\n\nexport function materializeGraph(\n  graphFunction: Readonly<GraphFunction>,\n  basis: GraphMaterializationBasis,\n): Readonly<GtlGraph> {\n  const graphFunctionDigest = sha256Canonical(graphFunction as unknown as JsonValue);\n  const shape = deriveMaterializedGraphShape(graphFunction, basis);\n  const body = {\n    graphFunctionRef: graphFunction.name,\n    graphFunctionDigest,\n    invocationAdmissionRef: basis.invocationAdmissionRef,\n    admittedInputRef: basis.admittedInputRef,\n    admittedInputDigest: basis.admittedInputDigest,\n    fanOutMaterializations: shape.fanOutMaterializations,\n    template: shape.template,\n  };\n  const materializationDigest = sha256Canonical(body as unknown as JsonValue);\n  const graph = deepFreeze({\n    kind: \"gtl_graph\" as const,\n    schemaVersion: \"5.0.0\" as const,\n    materializationRef: `graph-materialization://abiogenesis/${materializationDigest.slice(\"sha256:\".length)}`,\n    materializationDigest,\n    ...body,\n  }) as GtlGraph;\n  materializedGraphs.add(graph);\n  return graph;\n}\n"

SOURCE DATA repo://abiogenesis/build_tenants/abiogenesis/typescript/code/src/gtl/requirement_handoff.ts sha256:f383c054260c968bd77a20230ea0f5649934b4d8237b65f6f4b63c02a4196bd1
"import * as v from \"valibot\";\nimport type { ModulePublication, RootModuleArtifactBasis, ContractDeclaration } from \"./contracts.js\";\nimport { C, cCarrier } from \"./c_algebra.js\";\nimport { modulePublication } from \"./declarations.js\";\nimport { sha256Canonical } from \"../shared/digests.js\";\nimport type { JsonValue } from \"../shared/canonical_json.js\";\nimport { deepFreeze } from \"../shared/immutable.js\";\n\nconst ref = v.pipe(v.string(), v.minLength(1));\nconst digest = v.pipe(v.string(), v.regex(/^sha256:[0-9a-f]{64}$/));\nconst ordinal = v.pipe(v.number(), v.integer(), v.minValue(0));\nexport const CONTEXT_DECLARATION_SCHEMA = v.strictObject({\n  contextRef: ref, sourceLocator: ref, inventoryDigest: digest,\n  members: v.pipe(v.array(v.strictObject({ memberRef: ref, path: ref,\n    byteCount: ordinal, digest })), v.minLength(1)),\n});\nexport const REQUIREMENT_TERM_SCHEMA = v.strictObject({\n  requirementRef: ref,\n  sourceBindings: v.pipe(v.array(v.strictObject({ contextRef: ref, memberRef: ref,\n    memberDigest: digest, startByte: ordinal, endByte: ordinal, spanDigest: digest })), v.minLength(1)),\n});\nexport const GTL_CONTRACT_FULFILLMENT_BINDING_SCHEMA = v.strictObject({\n  obligationRef: ref, requirementRef: ref,\n  realizationContractRef: v.nullable(ref), proofContractRef: v.nullable(ref),\n  proofPolicyRef: v.nullable(ref), proofShapeRef: v.nullable(ref),\n});\nexport const REQUIREMENT_HANDOFF_DECLARATION_SCHEMA = v.strictObject({\n  declarationRef: ref, graphFunctionRef: ref, sourceRoleRef: ref,\n  context: CONTEXT_DECLARATION_SCHEMA,\n  terms: v.pipe(v.array(REQUIREMENT_TERM_SCHEMA), v.minLength(1)),\n  fulfillmentBindings: v.pipe(v.array(GTL_CONTRACT_FULFILLMENT_BINDING_SCHEMA), v.minLength(1)),\n});\nexport interface ContextDeclaration {\n  readonly contextRef: string; readonly sourceLocator: string; readonly inventoryDigest: `sha256:${string}`;\n  readonly members: readonly { readonly memberRef: string; readonly path: string; readonly byteCount: number; readonly digest: `sha256:${string}` }[];\n}\nexport interface RequirementTerm {\n  readonly requirementRef: string;\n  readonly sourceBindings: readonly { readonly contextRef: string; readonly memberRef: string; readonly memberDigest: `sha256:${string}`;\n    readonly startByte: number; readonly endByte: number; readonly spanDigest: `sha256:${string}` }[];\n}\nexport interface GtlContractFulfillmentBinding {\n  readonly obligationRef: string; readonly requirementRef: string;\n  readonly realizationContractRef: string | null; readonly proofContractRef: string | null;\n  readonly proofPolicyRef: string | null; readonly proofShapeRef: string | null;\n}\nexport interface GtlRequirementHandoffDeclaration {\n  readonly declarationRef: string; readonly graphFunctionRef: string; readonly sourceRoleRef: string;\n  readonly context: ContextDeclaration; readonly terms: readonly RequirementTerm[];\n  readonly fulfillmentBindings: readonly GtlContractFulfillmentBinding[];\n}\nconst unique = (xs: readonly string[]) => new Set(xs).size === xs.length;\nexport function isRequirementHandoffDeclaration(value: unknown): value is GtlRequirementHandoffDeclaration {\n  if (!v.is(REQUIREMENT_HANDOFF_DECLARATION_SCHEMA, value)) return false;\n  const { context, terms, fulfillmentBindings: bindings } = value;\n  return unique(context.members.map(x => x.memberRef)) && unique(context.members.map(x => x.path)) &&\n    context.inventoryDigest === sha256Canonical(context.members as unknown as JsonValue) &&\n    unique(terms.map(x => x.requirementRef)) && unique(bindings.map(x => x.obligationRef)) &&\n    bindings.length === terms.length && unique(bindings.map(x => x.requirementRef)) &&\n    bindings.every((x, i) => x.requirementRef === terms[i]!.requirementRef) &&\n    terms.every(term => term.sourceBindings.every(source => {\n      const member = context.members.find(x => x.memberRef === source.memberRef);\n      return source.contextRef === context.contextRef && member !== undefined &&\n        member.digest === source.memberDigest && source.startByte < source.endByte &&\n        source.endByte <= member.byteCount;\n    }));\n}\nexport function constructRequirementHandoffDeclaration(value: GtlRequirementHandoffDeclaration): Readonly<GtlRequirementHandoffDeclaration> {\n  if (!isRequirementHandoffDeclaration(value)) throw new TypeError(\"invalid requirement handoff declaration\");\n  return deepFreeze(value);\n}\nexport function validRequirementHandoffPublication(publication: Readonly<ModulePublication>): boolean {\n  const rows = publication.requirementHandoffs;\n  if (rows === undefined) return !publication.graphFunctions.some(g => g.declarations[\"abg.requirement_handoff\"] !== undefined);\n  return Array.isArray(rows) && unique(rows.map(x => x.declarationRef)) &&\n    unique(rows.map(x => x.graphFunctionRef)) && rows.every(row =>\n      isRequirementHandoffDeclaration(row) && publication.graphFunctions.filter(g =>\n        g.name === row.graphFunctionRef && g.declarations[\"abg.requirement_handoff\"] === row.declarationRef &&\n        g.inputs.length === 1 && g.inputs[0] === REQUIREMENT_HANDOFF_IDS.inputContractRef &&\n        g.outputs.length === 1 && g.outputs[0] === REQUIREMENT_HANDOFF_IDS.outputContractRef && g.effects.length === 0).length === 1 &&\n      row.fulfillmentBindings.every(binding => [binding.realizationContractRef, binding.proofContractRef].every(ref =>\n        ref === null || publication.contracts.filter(c => c.contractRef === ref && c.contractKind === \"output\").length === 1))) &&\n    publication.graphFunctions.every(g => g.declarations[\"abg.requirement_handoff\"] === undefined ||\n      rows.filter(row => row.declarationRef === g.declarations[\"abg.requirement_handoff\"] && row.graphFunctionRef === g.name).length === 1);\n}\n\nconst scope = \"abiogenesis/requirement-handoff\";\nexport const REQUIREMENT_HANDOFF_IDS = Object.freeze({\n  moduleRef: `module://${scope}@5`, programRef: `program://${scope}@5`,\n  graphFunctionRef: `graph-function://${scope}@5`, graphRef: `graph://${scope}@5`,\n  nodeRef: `node://${scope}@5`, startRef: `start://${scope}@5`, armId: `arm://${scope}@5`,\n  implementationRef: `implementation://${scope}-fd@5`, implementationBindingRef: `implementation-binding://${scope}-fd@5`,\n  inputContractRef: `contract://${scope}/input@5`, outputContractRef: `contract://${scope}/output@5`,\n  failureContractRef: `contract://${scope}/failure@5`, refusalContractRef: `contract://${scope}/refusal@5`,\n  evidenceContractRef: `contract://${scope}/evidence@5`, judgmentContractRef: `contract://${scope}/judgment@5`,\n  transitionContractRef: `contract://${scope}/transition@5`, closureContractRef: `contract://${scope}/closure@5`,\n  judgmentPredicateRef: `predicate://${scope}/transfer@5`,\n});\nexport function constructRequirementHandoffModulePublication(\n  artifact: RootModuleArtifactBasis,\n): Readonly<ModulePublication> {\n  const ids = REQUIREMENT_HANDOFF_IDS;\n  const contract = (contractRef: string, kind: ContractDeclaration[\"contractKind\"], valueKind: string): ContractDeclaration =>\n    ({ contractRef, contractVersion: \"5.0.0\", contractKind: kind, valueKind });\n  const binding = { kind: \"implementation_binding\" as const, bindingRef: ids.implementationBindingRef,\n    implementationRef: ids.implementationRef, packageName: artifact.packageName, packageVersion: artifact.packageVersion,\n    modulePath: \"build/code/src/implementation/requirement_handoff.js\", namedSymbol: \"realizeRequirementHandoff\",\n    computeRegime: \"F_D\" as const, inputContractRef: ids.inputContractRef, outputContractRef: ids.outputContractRef,\n    failureContractRef: ids.failureContractRef, refusalContractRef: ids.refusalContractRef };\n  const closure = { kind: \"closure_contract\" as const, closureContractRef: ids.closureContractRef,\n    predicateRef: ids.judgmentPredicateRef, evidenceContractRef: ids.evidenceContractRef, resultContractRef: ids.outputContractRef,\n    refusal