onRef,\n        ...(parentFrameId === null ? {} : { parentFrameId }),\n      };\n      const frameLineageDigest = sha256Canonical(\n        frameLineageBody as unknown as JsonValue,\n      );\n      const frameLineageId =\n        `frame-lineage://abiogenesis/${frameLineageDigest.slice(\"sha256:\".length)}`;\n      const frameBody = {\n        frameLineageId,\n        attempt: 1 as const,\n        parentFrameId,\n        runId,\n        graphCallId,\n        executionBasisRef: executionBasis.basisRef,\n        invocationRef: executionBasis.invocationRef,\n        admittedInputRef: executionBasis.rawInputAdmissionRef,\n        admittedInputDigest: executionBasis.rawInputDigest,\n      };\n      const frameDigest = sha256Canonical(frameBody as unknown as JsonValue);\n      const frameId =\n        `frame://abiogenesis/${frameDigest.slice(\"sha256:\".length)}`;\n      const frameStartedAt = captureNativeFrameBoundary(store);\n      const frameEvent = admitRuntimeEvent(store, {\n        kind: \"frame_opened\",\n        eventTime: sampleNativeEventTime(),\n        aggregateType: \"frame\",\n        aggregateId: frameId,\n        parentAggregateId: graphCallId,\n        causationEventRefs: [graphCallEvent.eventId],\n        correlationId: basis.correlationId,\n        workflowVersion: \"5.0.0\",\n        scopeClass: \"run\",\n        basisId: executionBasis.basisRef,\n        runId,\n        graphFunctionRef: executionBasis.graphFunctionRef,\n        materializationRef: executionBasis.graphRef,\n        graphCallId,\n        frameId,\n        frameLineageId,\n        payload: { frameId, frameDigest, ...frameBody },\n      });\n      observeNativeFrameLiveness(store, frameEvent, frameStartedAt, frameStartedAt);\n      frameClock = { opening: frameEvent, startedAt: frameStartedAt };\n      const frame = deepFreeze({\n        frameId,\n        frameDigest,\n        ...frameBody,\n        openEventRef: frameEvent.eventId,\n      }) as OpenedFrame;\n\n      const scopeBody = {\n        executionBasisRef: executionBasis.basisRef,\n        executionBasisDigest: executionBasis.basisDigest,\n        invocationAdmissionRef: executionBasis.invocationAdmissionRef,\n        invocationRef: executionBasis.invocationRef,\n        programRef: executionBasis.programRef,\n        graphFunctionRef: executionBasis.graphFunctionRef,\n        graphRef: executionBasis.graphRef,\n        runId,\n        runDigest,\n        runOpenEventRef,\n        graphCallId,\n        graphCallDigest,\n        graphCallOpenEventRef: graphCallEvent.eventId,\n        frameId,\n        frameDigest,\n        frameLineageId,\n        frameOpenEventRef: frameEvent.eventId,\n      };\n      const scopeDigest = sha256Canonical(scopeBody as unknown as JsonValue);\n      const scope = deepFreeze({\n        kind: \"opened_traversal_scope\" as const,\n        schemaVersion: \"5.0.0\" as const,\n        scopeRef:\n          `traversal-scope://abiogenesis/${scopeDigest.slice(\"sha256:\".length)}`,\n        scopeDigest,\n        ...scopeBody,\n      }) as OpenedTraversalScope;\n      openedScopes.add(scope);\n      return deepFreeze({\n        kind: \"traversal_scope_open_admission\" as const,\n        schemaVersion: \"5.0.0\" as const,\n        disposition: \"opened\" as const,\n        scopeClass: context.kind,\n        run: openedRun,\n        graphCall,\n        frame,\n        scope,\n      });\n    },\n  );\n  if (committed.successorPrefix === null) {\n    throw new TypeError(\"scope opening produced no durable successor prefix\");\n  }\n  if (frameClock !== null) {\n    const clock = frameClock as Readonly<{ opening: RuntimeEvent; startedAt: NativeFrameBoundarySample }>;\n    retainNativeFrameClock(store, clock.opening, clock.startedAt);\n  }\n  return deepFreeze({\n    ...committed.value,\n    successorPrefix: committed.successorPrefix,\n  }) as OpenTraversalScopeAdmission;\n}\n\n/** Cold selection by an admitted frame, sharing the existing scope validator.\n * The events remain the carrier; no persisted parent stack is reconstructed. */\nexport function projectOpenedTraversalScopeForFrameAtPrefix(\n  prefix: ValidatedRuntimeEventPrefix, frameId: string,\n): OpenedTraversalScope | null {\n  const rows = runtimeEventsFromValidatedPrefix(prefix);\n  const frames = rows.filter(e => e.kind === \"frame_opened\" && e.aggregateId === frameId);\n  const frame = frames.length === 1 ? frames[0] : undefined;\n  if (frame === undefined || !isRecord(frame.payload) || typeof frame.graphCallId !== \"string\" || typeof frame.runId !== \"string\") return null;\n  const graphRows = rows.filter(e => e.kind === \"graph_call_opened\" && e.aggregateId === frame.graphCallId);\n  const runRows = rows.filter(e => e.kind === \"run_segment_opened\" && e.aggregateId === frame.runId);\n  const graph = graphRows.length === 1 ? graphRows[0] : undefined;\n  const run = runRows.length === 1 ? runRows[0] : undefined;\n  const execution = rehydrateExecutionBasisAtPrefix(prefix, frame.basisId);\n  if (execution === null || graph === undefined || run === undefined || !isRecord(graph.payload) || !isRecord(run.payload) ||\n    typeof graph.payload.graphCallDigest !== \"string\" || typeof run.payload.runDigest !== \"string\" ||\n    typeof frame.payload.frameDigest !== \"string\" || typeof frame.frameLineageId !== \"string\") return null;\n  const body = { executionBasisRef: execution.basisRef, executionBasisDigest: execution.basisDigest,\n    invocationAdmissionRef: execution.invocationAdmissionRef, invocationRef: execution.invocationRef,\n    programRef: execution.programRef, graphFunctionRef: execution.graphFunctionRef, graphRef: execution.graphRef,\n    runId: frame.runId, runDigest: run.payload.runDigest, runOpenEventRef: run.eventId,\n    graphCallId: frame.graphCallId, graphCallDigest: graph.payload.graphCallDigest, graphCallOpenEventRef: graph.eventId,\n    frameId, frameDigest: frame.payload.frameDigest, frameLineageId: frame.frameLineageId, frameOpenEventRef: frame.eventId };\n  const scopeDigest = sha256Canonical(body);\n  return rehydrateOpenedTraversalScopeAtPrefix(prefix, { ...body, scopeDigest,\n    scopeRef: `traversal-scope://abiogenesis/${scopeDigest.slice(7)}` });\n}\n"

SOURCE DATA repo://abiogenesis/build_tenants/abiogenesis/typescript/code/src/abg/traversal_transition.ts sha256:91da813b3a661a96784403e01b2e3252963001b98fdf38a14b659188d5304354
"import { isRecord } from \"../shared/admission_predicates.js\";\nimport type { RawAdmittedValue } from \"../validator/raw_admission.js\";\nimport type {\n  BlockedRouteAdmissionEvidence,\n  FanOutRouteAdmissionEvidence,\n  HoldRouteAdmissionEvidence,\n  InteractionResumeRouteAdmissionEvidence,\n  RecursionRouteAdmissionEvidence,\n  RetryRouteAdmissionEvidence,\n  RouteAdmissionEvidence,\n  RouteCandidate,\n  StructuralIdentityRouteAdmissionEvidence,\n} from \"./traversal_route.js\";\nimport type { JsonValue } from \"../shared/canonical_json.js\";\nimport { sha256Canonical } from \"../shared/digests.js\";\nimport { deepFreeze } from \"../shared/immutable.js\";\n\nexport type TraversalTransitionEvidence =\n  | BlockedRouteAdmissionEvidence\n  | FanOutRouteAdmissionEvidence\n  | HoldRouteAdmissionEvidence\n  | InteractionResumeRouteAdmissionEvidence\n  | RecursionRouteAdmissionEvidence\n  | RetryRouteAdmissionEvidence\n  | RouteAdmissionEvidence\n  | StructuralIdentityRouteAdmissionEvidence\n  | null;\n\nexport type RouteCandidateBody = Omit<\n  RouteCandidate,\n  \"kind\" | \"schemaVersion\" | \"candidateRef\" | \"candidateDigest\"\n>;\n\nexport interface TraversalRouteBodySource {\n  readonly routeKind: RouteCandidate[\"routeKind\"];\n  readonly declarationRef: string;\n  readonly declarationDigest: `sha256:${string}`;\n  readonly sourceCursorRef: string;\n  readonly sourceCursorDigest: `sha256:${string}`;\n  readonly targetCursorRef: string | null;\n  readonly targetCursorDigest: `sha256:${string}` | null;\n  readonly cCallRef: string | null;\n  readonly judgmentRef: string | null;\n  readonly consumedAvailabilityRefs: readonly string[] | null;\n  readonly contractRef: string | null;\n  readonly replayStateDigest: `sha256:${string}` | null;\n  readonly boundInput?: RawAdmittedValue<Readonly<Record<string, JsonValue>>>;\n  readonly registeredSelectionApplicationRef?: string;\n  readonly nextActionProjectionRef?: string;\n  readonly nextActionProjectionDigest?: `sha256:${string}`;\n  readonly nextActionProjection?: Readonly<object>;\n  readonly graphSpanReentryProjectionRef?: string;\n  readonly graphSpanReentryProjectionDigest?: `sha256:${string}`;\n  readonly graphSpanReentryProjection?: Readonly<object>;\n}\n\nexport type TraversalTransitionCandidateBody =\n  | Readonly<{\n      kind: \"traversal_transition_candidate\";\n      schemaVersion: \"5.0.0\";\n      transitionClass: \"route\";\n      route: RouteCandidate;\n      evidence: TraversalTransitionEvidence;\n      terminalizeRun: boolean;\n    }>\n  | Readonly<{\n      kind: \"traversal_transition_candidate\";\n      schemaVersion: \"5.0.0\";\n      transitionClass: \"retry\";\n      route: RouteCandidate;\n      evidence:\n        | RetryRouteAdmissionEvidence\n        | StructuralIdentityRouteAdmissionEvidence\n        | null;\n      retryInput: Readonly<Record<string, JsonValue>>;\n      terminalizeRun: false;\n    }>;\n\nexport type TraversalTransitionCandidate = TraversalTransitionCandidateBody &\n  Readonly<{\n    candidateRef: string;\n    candidateDigest: `sha256:${string}`;\n  }>;\n\nfunction hasExactKeys(\n  value: Readonly<Record<string, unknown>>,\n  expectedKeys: readonly string[],\n): boolean {\n  const actual = Object.keys(value).sort();\n  const expected = [...expectedKeys].sort();\n  return actual.length === expected.length &&\n    actual.every((key, index) => key === expected[index]);\n}\n\nfunction isExactTransitionEvidence(\n  value: unknown,\n): value is TraversalTransitionEvidence {\n  if (value === null) return true;\n  if (!isRecord(value)) return false;\n  switch (value.evidenceClass) {\n    case \"blocked\":\n      return hasExactKeys(value, [\n        \"cCall\", \"evidenceClass\", \"graphFunction\", \"judgmentEventRef\",\n        \"judgmentRef\", \"reasonRef\", \"resultRef\", \"stoppedProgresses\",\n      ]) && Array.isArray(value.stoppedProgresses);\n    case \"fan_out\":\n      return hasExactKeys(value, [\n        \"application\", \"cCall\", \"completedProgresses\", \"completion\",\n        \"evidenceClass\", \"graphFunction\", \"judgment\", \"result\",\n      ]) && Array.isArray(value.completedProgresses);\n    case \"hold\":\n      return hasExactKeys(value, [\n        \"cCall\", \"evidenceClass\", \"graphFunction\", \"judgment\", \"result\",\n      ]);\n    case \"interaction_resume\":\n      return hasExactKeys(value, [\n        \"cCall\", \"completedProgresses\", \"evidenceClass\", \"graphFunction\",\n        \"judgment\", \"result\", \"resume\",\n      ]) && Array.isArray(value.completedProgresses);\n    case \"judged\":\n      return hasExactKeys(value, [\n        \"cCall\", \"completedProgresses\", \"evidenceClass\", \"graphFunction\",\n        \"judgment\", \"result\",\n      ]) && Array.isArray(value.completedProgresses);\n    case \"recursion\":\n      return hasExactKeys(value, [\n        \"application\", \"cCall\", \"evidenceClass\", \"foldback\", \"judgment\",\n        \"preparationRefusal\", \"result\",\n      ]) && (value.foldback === null || isRecord(value.foldback)) &&\n        (value.preparationRefusal === null ||\n          isRecord(value.preparationRefusal));\n    case \"retry\":\n      return hasExactKeys(value, [\n        \"cCall\", \"evidenceClass\", \"graphFunction\", \"progress\",\n      ]);\n    case \"structural_identity\":\n      return hasExactKeys(value, [\n        \"completedProgresses\", \"completionClass\",\n        \"completionWitnessEventRef\", \"evidenceClass\", \"graphFunction\",\n      ]) && value.completionClass === \"structural_identity_success\" &&\n        Array.isArray(value.completedProgresses);\n    default:\n      return false;\n  }\n}\n\nexport function projectTraversalRouteBody(\n  route: TraversalRouteBodySource,\n): RouteCandidateBody | null {\n  const nextActionPresence = [\n    route.nextActionProjectionRef,\n    route.nextActionProjectionDigest,\n    route.nextActionProjection,\n  ].map((value) => value !== undefined);\n  const graphSpanPresence = [\n    route.graphSpanReentryProjectionRef,\n    route.graphSpanReentryProjectionDigest,\n    route.graphSpanReentryProjection,\n  ].map((value) => value !== undefined);\n  if (\n    (route.registeredSelectionApplicationRef !== undefined &&\n      (typeof route.registeredSelectionApplicationRef !== \"string\" || route.registeredSelectionApplicationRef.length === 0 || route.boundInput === undefined)) ||\n    route.consumedAvailabilityRefs === null ||\n    route.replayStateDigest === null ||\n    (nextActionPresence.some(Boolean) && !nextActionPresence.every(Boolean)) ||\n    (graphSpanPresence.some(Boolean) && !graphSpanPresence.every(Boolean))\n  ) return null;\n  return {\n    ...(route.boundInput === undefined ? {} : { boundInput: route.boundInput }),\n    ...(route.registeredSelectionApplicationRef === undefined ? {} : { registeredSelectionApplicationRef: route.registeredSelectionApplicationRef }),\n    routeKind: route.routeKind,\n    declarationRef: route.declarationRef,\n    declarationDigest: route.declarationDigest,\n    sourceCursorRef: route.sourceCursorRef,\n    sourceCursorDigest: route.sourceCursorDigest,\n    targetCursorRef: route.targetCursorRef,\n    targetCursorDigest: route.targetCursorDigest,\n    cCallRef: route.cCallRef,\n    judgmentRef: route.judgmentRef,\n    consumedAvailabilityRefs: route.consumedAvailabilityRefs,\n    contractRef: route.contractRef,\n    replayStateDigest: route.replayStateDigest,\n    ...(route.nextActionProjectionRef === undefined\n      ? {}\n      : {\n          nextActionProjectionRef: route.nextActionProjectionRef,\n          nextActionProjectionDigest: route.nextActionProjectionDigest!,\n          nextActionProjection: route.nextActionProjection! as unknown as\n            Readonly<Record<string, JsonValue>>,\n        }),\n    ...(route.graphSpanReentryProjectionRef === undefined\n      ? {}\n      : {\n          graphSpanReentryProjectionRef: route.graphSpanReentryProjectionRef,\n          graphSpanReentryProjectionDigest:\n            route.graphSpanReentryProjectionDigest!,\n          graphSpanReentryProjection:\n            route.graphSpanReentryProjection! as unknown as\n              Readonly<Record<string, JsonValue>>,\n        }),\n  };\n}\n\nexport function routeCandidateBody(\n  value: unknown,\n): RouteCandidateBody | null {\n  if (!isRecord(value)) return null;\n  const route = value;\n  const required = [\n    \"cCallRef\", \"consumedAvailabilityRefs\", \"contractRef\", \"declarationDigest\",\n    \"declarationRef\", \"judgmentRef\", \"replayStateDigest\", \"routeKind\",\n    \"sourceCursorDigest\", \"sourceCursorRef\", \"targetCursorDigest\",\n    \"targetCursorRef\",\n  ];\n  const nextAction = Object.hasOwn(route, \"nextActionProjectionRef\")\n    ? [\n        \"nextActionProjection\", \"nextActionProjectionDigest\",\n        \"nextActionProjectionRef\",\n      ]\n    : [];\n  const graphSpan = Object.hasOwn(route, \"graphSpanReentryProjectionRef\")\n    ? [\n        \"graphSpanReentryProjection\", \"graphSpanReentryProjectionDigest\",\n        \"graphSpanReentryProjectionRef\",\n      ]\n    : [];\n  if (!hasExactKeys(route, [\n    \"candidateDigest\", \"candidateRef\", \"kind\", \"schemaVersion\",\n    ...required, ...nextAction, ...graphSpan, ...(Object.hasOwn(route, \"registeredSelectionApplicationRef\") ? [\"registeredSelectionApplicationRef\"] : []), ...(Object.hasOwn(route, \"boundInput\") ? [\"boundInput\"] : []),\n  ])) return null;\n  return projectTraversalRouteBody(\n    route as unknown as TraversalRouteBodySource,\n  );\n}\n\nexport function isRouteCandidate(value: unknown): value is RouteCandidate {\n  if (!isRecord(value)) return false;\n  const body = routeCandidateBody(value);\n  if (\n    body === null ||\n    value.kind !== \"traversal_route_candidate\" ||\n    value.schemaVersion !== \"5.0.0\" ||\n    typeof value.candidateDigest !== \"string\" ||\n    typeof value.candidateRef !== \"string\"\n  ) return false;\n  const digest = sha256Canonical(body as unknown as JsonValue);\n  return value.candidateDigest === digest &&\n    value.candidateRef ===\n      `route-candidate://abiogenesis/${digest.slice(\"sha256:\".length)}`;\n}\n\nexport function completeRouteCandidate(\n  body: RouteCandidateBody,\n): RouteCandidate {\n  const candidateDigest = sha256Canonical(body as unknown as JsonValue);\n  const candidate = deepFreeze({\n    kind: \"traversal_route_candidate\" as const,\n    schemaVersion: \"5.0.0\" as const,\n    candidateRef:\n      `route-candidate://abiogenesis/${candidateDigest.slice(\"sha256:\".length)}`,\n    candidateDigest,\n    ...body,\n  });\n  if (!isRouteCandidate(candidate)) {\n    throw new TypeError(\"traversal route candidate is not exact\");\n  }\n  return candidate;\n}\n\nexport function isTraversalTransitionCandidate(\n  value: unknown,\n): value is TraversalTransitionCandidate {\n  if (!isRecord(value)) return false;\n  const retry = value.transitionClass === \"retry\";\n  if (\n    value.transitionClass !== \"route\" && !retry ||\n    !hasExactKeys(value, [\n      \"candidateDigest\", \"candidateRef\", \"evidence\", \"kind\",\n      ...(retry ? [\"retryInput\"] : []),\n      \"route\", \"schemaVersion\", \"terminalizeRun\", \"transitionClass\",\n    ]) ||\n    value.kind !== \"traversal_transition_candidate\" ||\n    value.schemaVersion !== \"5.0.0\" ||\n    typeof value.candidateDigest !== \"string\" ||\n    typeof value.candidateRef !== \"string\" ||\n    !isRouteCandidate(value.route) ||\n    !isExactTransitionEvidence(value.evidence) ||\n    typeof value.terminalizeRun !== \"boolean\" ||\n    (retry && !isRecord(value.retryInput))\n  ) return false;\n  const evidenceClass = value.evidence === null\n    ? \"none\"\n    : value.evidence.evidenceClass;\n  if (\n    retry\n      ? value.route.routeKind !== \"retry\" ||\n        value.terminalizeRun !== false ||\n        ![\"none\", \"retry\", \"structural_identity\"].includes(evidenceClass)\n      : value.route.routeKind === \"retry\"\n  ) return false;\n  const { candidateRef, candidateDigest, ...body } = value;\n  const digest = sha256Canonical(body as unknown as JsonValue);\n  return candidateDigest === digest && candidateRef ===\n    `traversal-transition-candidate://abiogenesis/${digest.slice(\"sha256:\".length)}`;\n}\n\nexport function completeTraversalTransitionCandidate(\n  body: TraversalTransitionCandidateBody,\n): TraversalTransitionCandidate {\n  const candidateDigest = sha256Canonical(body as unknown as JsonValue);\n  const candidate = deepFreeze({\n    ...body,\n    candidateRef:\n      `traversal-transition-candidate://abiogenesis/${candidateDigest.slice(\"sha256:\".length)}`,\n    candidateDigest,\n  });\n  if (!isTraversalTransitionCandidate(candidate)) {\n    throw new TypeError(\"traversal transition candidate is not exact\");\n  }\n  return candidate;\n}\n"

SOURCE DATA repo://abiogenesis/build_tenants/abiogenesis/typescript/design/T287_DEFAULT_GOVERNANCE_LIBRARY_DESIGN.md sha256:8f87b9d6c476ed27650c1904bbfdaa3059d7e0c1b8912a74bf9e92b922a88c2b
"# T-287 Default Governance Library\n\nAccepted HOW under `execution.md#s5-acceptance-and-implementation-grant`. Exact STDO v2.5.1-rc.1; Product/Design/Owner, Reuse/Foundation and End-To-End Interface Integration. Source proposal SHA-256 `f9e7f51a2bd12ee0d27e5e0d3a9861545a941e139835ab87097144e8e053fe2a`; focused review SHA-256 `fc71d3c2cae63de284b0ef28bff11fec655bf790d9922674d1e3e7289712efda`. Immutable history: `.ai-workspace/comments/codex/20260928_FRAMED_GOVERNANCE/default-library-plan.md` and `default-library-plan-review-02.md`. This tenant document owns the technical relation.\n\nPublish one ordinary default-library module with seven callable purposes:\nrecursive Executive, induction, specification, design, construction, testing\nand UAT. Construction wraps the existing native coding-worker GraphFunction.\nThe other work wrappers reuse existing native work/assessment/execution owners.\nTheir GraphFunctions have distinct declared purposes, contracts and policy\nassets; selection invokes a permitted registered wrapper, not a label in a\nuniversal runtime dispatcher. Consumers select/restrict/replace these ordinary\ncatalogue contributions. There is no required induction→specification→design\nsequence, role hierarchy or graph generation.\n\n## Common application contract and coverage\n\nUse one small typed library input/result, `governance_work_state`: original task\nand exact selected source identities; declared outcome/criterion and authority\nreferences; applicable installed policy/assets; currently supplied or observed\nworksite/evidence coordinates; requested bounded work and retained unresolved\noutcomes. These are application data, not a new ABG ledger or obligation engine.\nA child returns its bounded product/measurement, source/producer correspondence,\nexplicit gaps and the conserved parent state. It cannot replace originals,\nstrengthen its grant, discard valid evidence or certify parent convergence.\n\nThe table specifies callable coverage, not mandatory calls. “Ready” below means\nthe bounded capability result exists; it does not mean the application is done.\nAll semantic interpretation, suitability and sufficiency judgments are F_P.\nF_D performs declared copying, schema/identity checks and total control rules.\n\n| Callable purpose | Typed work/result within state | Selected frame and criterion | Effects and completion/gap | Actual invocation and retained assets |\n|---|---|---|---|---|\n| **Executive**: select/revise registered work and reevaluate the original outcome | State → same state with admitted choice/returned evidence and parent evaluation | Executive + consumer outcome criteria; purpose/contract fit, proportionality, preserved residuals | Selection is effect-free. Closure requires the explicit parent outcome evaluation; unsupported capability/input stays gap | S3 `registered_selection_task`/raw binder + S4 declared recursion. Open parent sufficiency uses the existing read-only native assessment; F_D only projects its admitted verdict into the declared recursion termination rule |\n| **Induction**: establish task model, context, assumptions and unknowns | Complete original source → bounded task-model asset plus unresolved questions | Worker/induction; source faithfulness, modality, conflicting statements and uncertainty | Read selected sources; write only selected model asset when needed. No invented resolution of unknowns | Fixed native-work workflow; applicable separate assessment. Retain `native-intent-declarations.mjs` policy content and headings as reusable source, adapting its narrow Intent outcome into explicit induction coverage |\n| **Specification**: state requested behavior and testable criteria | Source/model and any already-valid requirements → behavior/criterion asset | Product/Specification; source-grounded behavior, boundaries and meaningful proof obligations | Scoped asset writes; absent source/authority remains gap. Does not require a freshly generated induction asset | Fixed native-work and applicable native-assessment calls. Retain donor product/requirements required-content and common rubric; remove fixed predecessor-stage requirements |\n| **Design**: propose a realizable bounded change and checks | Source/criteria/current worksite/reusable design → selected artifact and command plan | Design + interface integration; actual context, feasibility, preservation and executable proof | Scoped design asset only. Unknown dependency/capacity remains explicit; no guessed controls | Fixed native work/assessment; retain donor design content and executable-proof criterion, including actual inventory and declared capacity |\n| **Construction**: realize the selected work | Bounded work order/current context → `NativeWorkspaceWorkObservation` folded into state | Worker/Construction; original outcomes and selected change scope | Existing native coding host reads/edits/runs permitted checks; actual before/after observations own effect truth. Report alone never proves success | Existing `NATIVE_WORKSPACE_WORK_IDS.graphFunctionRef`, `realizeNativeWorkspaceWork`; retain exact native task, scope and observation contracts |\n| **Testing**: establish reproducible executable behavior | Selected criteria/check plan plus actual candidate → native command/predicate observations and residuals | Testing/verification; meaningful tests of the actual candidate and declared expected observations | Permitted command/check effects and explicitly scoped verifier artifacts. Missing plan/tools/evidence remains gap | Existing native work may author a needed verifier/plan; existing C2 command GraphFunction executes the declared commands and returns typed observations. Reuse its unchanged native-source arm, or the explicitly proposed observed-input child extension below; never fabricate construction success |\n| **UAT**: independently assess selected user outcomes | Original source, independently authored oracle/rubric, exact candidate and execution evidence → consumer-declared assessment | Product/UAT + independent Reviewer; requested behavior in the selected usage context | Read-only fresh assessment; use declared C2 probes if required. Unsatisfied/indeterminate outcomes remain open | Existing native assessment GraphFunction with installed schema asset and exact source/candidate/rubric digests. Retain donor evidence/common-rubric meaning, not its unconditional final stage |\n\nPolicy rows and source assets are declaration data. Existing run-environment\nroles remain `selector`, native `constructor` and `assessor` (plus C2's command\nexecutor when used); they do not create an arbitrary actor roster. The registered\nwrapper fixes its policy selection, and its mechanically constructed task names\nthe exact applicable policy/rubric asset. Existing owned assembly binds the task\nand admitted source context. A shared native leaf retains its fixed identity;\nwe do not clone/rename it to evade native-work authority checks.\n\n## Selected execution relation\n\nThe optional recursive Executive performs parent evaluation → owned preparation →\none frame-bound F_P synthesis → F_D choice projection → one exact permitted\nwrapper → ordinary child Result/foldback → parent reevaluation. The Program\nfixes the registered domain, workflow callees and finite recursion bound. No\nConstructionComposition or mandatory stage sequence is introduced.\n\nThe synthesis maps the conserved problem to registered contributions with\ninterpretation, contribution/reason/support/evidence, relevant dependencies,\nexplicit gaps, and an explicitly selected next member. Suitability, priority,\ndependency interpretation and sufficiency remain F_P judgments. F_D validates\nclosed reference/contract relations and transports the chosen member; it never\nranks, fills a gap, finds a ready dependency or schedules every listed member.\nEvery dependency must name another contribution in that same current response;\nprior completed work outside the mapping is cited through evidenceRefs. These\ncross-field rules are stated in the actual rendered response contract.\nLater admitted evidence may lawfully revise the mapping. Catalogue membership\nand purpose establish neither semantic suitability nor completion.\n\nThe library owns three application contracts. `framed_synthesis_task` carries\ncurrent conserved state and bounded actual worksite context. Raw\n`framed_synthesis_response` carries the current judgment, next member (or null\nwith a gap), explicit subject-evidence Result when needed, and revision reason\nand evidence. `framed_synthesis_result` conserves that raw judgment and input\nstate, adding mechanically bound input/task, selected environment/frame evidence,\ncontext and prior synthesis Result coordinates. The strict raw binder is shared\nby native completion and Result admission; it preserves observed values without\nstripping, repair or model-authored authority echoes.\n\nThe template declares `abg.framed_synthesis_locus` and\n`abg.framed_synthesis_projection`. The former is the F_P synthesis leaf; its\nimmediate successor is the fixed F_D projection and existing registered-selection\nsource. `gtl/stdo_run_environment.ts` recognizes this exact profile under the\nexplicit Program/run-environment selector role before interpreting payloads.\nInvalid applicable bindings refuse; unrelated F_P payloads remain ordinary data.\nAssembly uses the existing authenticated occurrence, run-environment source\nprojection, imported contract callback and admitted definition identities. It\nprojects only selected frame spans, purposes/contracts/effects, complete original\nsource and current observations. Catalog readiness bodies are not prompt input.\nThe existing selector identity projection includes invocationAdmissionRef so\npersisted assembly and cold replay join the same admitted environment.\nObserved Testing captures command and HTTP launch defaults at preparation only.\nIts shared input/task relation conserves every explicit declaration constraint\nagainst the admitted normalized environment; replay never reacquires ambient\nHOME, TMPDIR, LANG, LC_ALL or PATH from the reading process.\nActor admission supplies the consumed raw observation to the same binder; there\nis no duplicate assembly or history walk at completion.\n\nThe projection consumes the actual preceding admitted synthesis Result. It\ntransports `nextGraphFunctionRef`, reason/evidence and exact declared child\ncontract into the unchanged `registered_graph_choice` or existing gap primitive.\nNormal registered-selection admission and the workflow's fixed-callee/input\nchecks still own launch. Exact actual source Result identity comes from the\nexisting cursor input occurrence, never a model response field.\n\n**FS-C01:** current state stores only `{resultRef, resultDigest, basis, judgment}`.\nThe judgment is the compact raw current response; its basis includes the prior\nResult reference. It cannot contain a prior whole Result or input-state body.\nThe transient bound Result carries its current input state once so the following\nprojection needs no new retained edge across consumer/library semantics owners.\nThe projection discards that wrapper. Older complete mappings remain their\nordinary admitted C-call Results. Folded observations identify their synthesis\nResult and selected registered GraphFunction, conserving revision attribution\nwithout a second event ledger.\n\nEach work wrapper projects the common state into the existing native/C2 task,\ninvokes its fixed child, and folds its truthful observation back. **FS-C02:**\n`projectTraversalInputAtPrefix` already validates the retained child/result and\nfoldback relation. Its internal input-origin return retains that same computed\nobject; the authenticated native basis exposes it to the fold, which consumes\nits actual Result and CCall. This adds no serialized proof, cache, event or second\nprojection. Native, C2 and assessment actor coordinates come from the actual\ntyped child observation. In particular C2 has no `source.provenance.cCallRef`;\nits actual Result aggregate supplies the call coordinate. Root/direct input and\noccurrence/prefix validity remain unchanged.\n\nOnly the parent applies the declared total verdict rule to an independently\nassessed original outcome. A successful measurement of failing behavior folds\ntruthfully while the parent remains open. Neither reports, stage counts, file\npresence nor successful child closure establish the outcome. Unknown required\ninputs refuse before launch; original task/authority and unresolved support stay\nconserved through every mapping, choice and fold.\n\n### DL-I02: selected subject evidence and supplied work\n\n`subjectEvidenceRef` explicitly selects an actual folded observation Result.\nNative evidence may come from any selected non-assessment native capability;\nits purpose label does not restrict eligibility. Reuse the existing native\nsource projection, same-invocation/binding facts and current candidate after\nobservation. Testing with null subject evidence observes existing files; a\nselected missing or invalid native source refuses without fallback.\n\nUAT also accepts an actual C2 measurement Result for supplied work. Require its\nexact Result/digest/CCall/actor, same invocation/root implementation set/workspace,\nand the candidate at its current digest among protected task observations. The\nadmitted C2 observation already proves unchanged protected before/after files.\nThe assessment producer coordinate then denotes measurement provenance, never\nfile authorship. No dummy author or fabricated source Result is introduced.\nExisting native-work HOW's typed assessment already permits existing assets and\nconsumer-selected historical evidence. Producer support is scoped to its own\nadmitted files: native work uses file entries in its exact after-observation\n(the existing folded native dependency projection), and either C2 source arm\nuses its protected task observations. The candidate must be among those files\nat its current digest. Every producer dependency must still match the freshly\nobserved context; later intersecting writes or uncertain residue refuse through\nthe existing currentness owner. Absent future outputs and assessment inputs\nfirst authored afterward do not retroactively become producer dependencies.\n\nSeparately, fresh context binds every declared assessment source, candidate and\nrubric at its current digest. Newly authored assessment-only documents may\ntherefore accompany an earlier still-current native or C2 subject. Neither\nlatest-author selection nor a redundant command run is required. The assessment\nmust actually consume these current inputs; their presence does not prove\nadequacy. Existing native assessment requires a distinct fresh call/actor.\nPreparation and\nadmission share this exact local relation; parent outcome evaluation remains\nseparate. Explicitly selected crossed/stale evidence is never replaced silently.\n\nThe independent fixture selects ten exact read roots, and selects the oracle\nonce as rubric while retaining it in original/read-first context. Installed\nreadiness observes these roots after run-environment resources exist. Finite\nproof combines the unchanged faulty-candidate witness with a fresh Testing/UAT\nonly companion using the actually corrected supplied candidate and no author\ninvocation. Both use the same core archive and fresh Public result/replay. Event\ncitations connect frame/context, synthesis/revision, projected choice, child\nResult/fold and parent evaluation; no caller loop or prescribed schedule exists.\n\n## Concrete missing relation and smallest implementation boundary\n\nThe current native effect and assessment owners already exist. Their reusable\ntasks are **not** the existing ordered semantic-job envelope. In particular,\n`product/semantic_job.ts:865–873` requires the selected stage to equal the current\n`assets.length` position and checks declared assessed predecessors.\n`abg/semantic_job.ts:471–501` binds preparation/foldback to that envelope.\nImporting these helpers unchanged would restore the rejected lifecycle.\n\nThe missing relation is therefore **unordered library state ↔ an exactly owned\nnative task/observation**, including current context and admitted producer links.\nImplement it as a bounded projection/result correspondence under existing ABG\nowners, not a new effect, event family or execution entity:\n\n- New `gtl/default_library.ts`: ordinary module, wrapper templates, registered\n  domain, optional recursive Executive, policies, contracts and contributions.\n  Export through `gtl/index.ts`; add its publication to the existing\n  `scripts/generate-product-manifest.mjs` module list beside native work/C2.\n- New `product/default_library.ts` and packaged policy assets: typed state,\n  selected work-order/assessment/command-plan contracts and pure conservation\n  predicates. New `implementation/default_library.ts`: packaged projections and\n  the owned framed-synthesis prepared realization. No shell/native effects in these\n  adapters; the existing child implementations own them.\n- Use the current `abg/execution_basis.ts:159–240` owned occurrence authentication\n  for the preparation/fold projection. It already recovers current cursor input,\n  Program, implementation and workspace environment without an F_P-only\n  restriction. Add only the required binding arm at HoG preparation and ABG result\n  admission (`hog/ccall_lifecycle.ts`, `abg/c_call_outcome.ts`). Put the narrow\n  projection helpers in `abg/default_library.ts` under existing ABG authority;\n  this file adds no runtime entity or admission authority. Consume the bound\n  basis once and preserve its private reuse; no repeated declaration hashing,\n  full-graph event copy or another cache/proof carrier.\n- Preparation invokes existing `observeWorksiteContext` for declared current\n  input, constructs existing `NativeWorkspaceWorkTask` or C2 task and checks\n  exact scope. Assessment uses existing `NativeWorkspaceAssessmentSelection`\n  and installed schema resolution. Result admission authenticates the actual\n  selected child, same authority, raw/result relation and retained parent input.\n\nThis owner extension needs explicit S5 implementation authority; it is not\nclaimed delivered by the fixture. If its existing basis cannot supply the\nrequired occurrence/producer relation, return that exact seam before introducing\nanother carrier. The task must not fall back to a naked prompt, caller-side\nsnapshot/continuation loop or the ordered semantic-job helper.\n\n## DL-D01: observed-input Testing child — selected extension\n\nThe governing C2 HOW, `T287_W2_R3_C2_WORKSITE_COMMAND_EXECUTION_DESIGN.md:303–339`,\nexplicitly supports **root C2 only** for observed files and deliberately excludes\nchildren. This proposal amends that HOW boundary for one admitted Testing-child\ncomposition; it must not be described as already supported. The existing root\nbinding at `abg/execution_basis.ts:714–724` remains exact and unchanged. No Product\nconflict was found: COMPOSE-004/007/008 requires replayable composition with\npreserved, sufficient inputs; HANDLERS-001/003/005 requires exact admitted calls,\nreal observations and authority; BINDING-016–018 separates observations from\nimmutable authority. Product's Preparation/Execution boundary and default-library\nreuse require no invented author or gratuitous construction call. Implementation\nmust update only the owning C2 HOW's root-only exclusion and its affected joins;\nProduct, requirements, effect scope and Public operations stay fixed.\n\nThere are two distinct source cases. Native-source Testing retains its existing\ncompleted native Result, same-Run/reacquisition preparation and currentness laws.\nObserved-input Testing carries actual existing file observations, **no author\nclaim and no predecessor native/construction Result**. Its real F_D preparation\nResult proves task preparation, not file authorship. Keep\n`deriveSameRunWorksiteCommandSourceBasisAtPrefix`'s native/C1/C3 branches unchanged;\ndo not coerce observed files into `ProductInvocationSourceResultBasis`.\n\nUse one pure observed-child provenance projection in existing\n`abg/worksite_input_provenance.ts`, selected by the existing closed\n`sourceObservedInput` task arm and the actual declared C2 call boundary. It\nreturns the already-admitted input/preparation/result/judgment/route coordinates\nand selected observation set. This is an internal projection, with no new basis\nidentity, serialized carrier, event, cache, ledger or effect permission.\n\n1. **Input and acquisition.** The Testing wrapper receives the admitted parent\n   state and an explicit ordered file selection plus command/predicate/write\n   configuration. Its named `prepareObservedTestingTask` F_D leaf consumes the\n   existing owned occurrence basis; it derives A/W/grant from the current admitted\n   environment and original invocation. It uses existing worksite observation\n   operations for exactly those subjects and constructs the existing\n   `ObservedWorksiteCommandExecutionTask`. Nonempty/unique source rows, exact\n   subject/observation binding, source-set identity and protected territories\n   remain the existing constructor's law. Caller-provided file claims alone are\n   insufficient. This leaf executes no command and makes no suitability judgment.\n2. **Preparation admission and route.** The proposed library preparation guard\n   admits the exact task/observations only against that occurrence, declared\n   input and admitted implementation. The shared projector follows the current\n   parent basis, Run, invocation, workflow CCall and cursor to its actual preceding\n   advance route and successful, advancing preparation Result. It verifies the\n   exact declared preparation binding, Result/judgment causal refs and canonical\n   task/contract equality. Recover the preparation input through the existing\n 